Method.Source:
/// <summary>
/// Seeds one unchecked row per real company on first open, so the admin only ticks boxes
/// instead of keying company ids; companies created later are topped up on the next open.
/// Each row commits on its own with a duplicate-key catch - two sessions opening the form
/// at the same time both pass the exist() check, and the loser must skip, not crash.
/// </summary>
public void init()
{
    DataArea              dataArea;
    CELTCompanyCapability capability;

    while select Id from dataArea
        where dataArea.isVirtual == NoYes::No
    {
        if (!CELTCompanyCapability::exist(dataArea.Id))
        {
            try
            {
                ttsbegin;
                capability.clear();
                capability.CompanyId = dataArea.Id;
                capability.insert();
                ttscommit;
            }
            catch (Exception::DuplicateKeyException)
            {
                // Another session seeded this company between the check and the insert.
            }
        }
    }

    super();
}
